import{getWorld}from"#internal/workflow/runtime.js";import{HookNotFoundError}from"#compiled/@workflow/errors/index.js";async function releaseSessionHooksStep(e){"use step";let t=await getWorld(),n=await Promise.allSettled(e.tokens.map(async n=>{let r;try{r=await t.hooks.getByToken(n)}catch(e){if(HookNotFoundError.is(e))return;throw e}if(r.runId!==e.ownerRunId)throw Error(`Cannot release a session hook owned by another workflow.`);await t.events.create(e.ownerRunId,{correlationId:r.hookId,eventData:{token:n},eventType:`hook_disposed`,specVersion:r.specVersion})}));for(let e of n)if(e.status===`rejected`)throw e.reason}export{releaseSessionHooksStep};